import React, { useState, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { useDropzone } from 'react-dropzone';
import axios from 'axios';
import toast from 'react-hot-toast';
import Layout from '../components/Layout';
import { API } from '../context/AuthContext';

export default function UploadPage() {
  const [file, setFile] = useState(null);
  const [title, setTitle] = useState('');
  const [recipients, setRecipients] = useState([
    { email: '', name: '' }
  ]);
  const [message, setMessage] = useState('');
  const [loading, setLoading] = useState(false);

  const navigate = useNavigate();

  const onDrop = useCallback((accepted) => {
    if (accepted[0]) {
      setFile(accepted[0]);

      if (!title) {
        setTitle(
          accepted[0].name.replace('.pdf', '')
        );
      }
    }
  }, [title]);

  const {
    getRootProps,
    getInputProps,
    isDragActive
  } = useDropzone({
    onDrop,
    accept: {
      'application/pdf': ['.pdf']
    },
    maxFiles: 1
  });

  const addRecipient = () => {
    setRecipients([
      ...recipients,
      { email: '', name: '' }
    ]);
  };

  const removeRecipient = (i) => {
    setRecipients(
      recipients.filter((_, idx) => idx !== i)
    );
  };

  const updateRecipient = (i, field, val) => {
    const updated = [...recipients];
    updated[i][field] = val;
    setRecipients(updated);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!file) {
      toast.error('Please select a PDF file');
      return;
    }

    const validRecipients = recipients
      .map((r) => ({
        email: r.email.trim().toLowerCase(),
        name: r.name.trim(),
      }))
      .filter((r) => r.email);

    const duplicateEmails = validRecipients
      .map((r) => r.email)
      .filter((email, index, arr) => arr.indexOf(email) !== index);

    if (duplicateEmails.length) {
      toast.error('Duplicate recipient emails are not allowed');
      return;
    }

    if (!validRecipients.length) {
      toast.error('Add at least one recipient email');
      return;
    }

    setLoading(true);

    try {
      const formData = new FormData();

      formData.append('file', file);
      formData.append(
        'title',
        title || file.name
      );
      formData.append(
        'recipients',
        JSON.stringify(validRecipients)
      );
      formData.append('message', message);

      const res = await axios.post(
        `${API}/documents/upload`,
        formData,
        {
          headers: {
            'Content-Type': 'multipart/form-data'
          }
        }
      );

      toast.success(
        'Document uploaded! Now place signature locations.'
      );

      navigate(`/documents/${res.data.id}`);

    } catch (err) {
      toast.error(
        err.response?.data?.error || 'Upload failed'
      );
    } finally {
      setLoading(false);
    }
  };

  return (
    <Layout>

      {/* Header */}
      <div className="page-header">
        <h1 className="page-title">
          Upload Document
        </h1>

        <p className="page-subtitle">
          Upload a PDF and configure recipients
        </p>
      </div>

      {/* Body */}
      <div
        className="page-body"
        style={{
          display: 'flex',
          justifyContent: 'center',
          width: '100%',
          padding: '24px 0'
        }}
      >

        <form
          onSubmit={handleSubmit}
          style={{
            width: '100%',
            maxWidth: '1200px'
          }}
        >

          <div
            style={{
              display: 'grid',
              gridTemplateColumns: '2fr 1fr',
              gap: 28,
              alignItems: 'start'
            }}
          >

            {/* LEFT SIDE */}
            <div>

              {/* Upload Card */}
              <div
                style={{
                  background: 'var(--card)',
                  border: '1px solid var(--border)',
                  borderRadius: 24,
                  padding: 28,
                  marginBottom: 24
                }}
              >

                {/* Dropzone */}
                <div className="form-group">
                  <label className="label">
                    PDF DOCUMENT
                  </label>

                  <div
                    {...getRootProps()}
                    className={`dropzone ${isDragActive ? 'active' : ''}`}
                    style={{
                      minHeight: 240,
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      borderRadius: 20
                    }}
                  >

                    <input {...getInputProps()} />

                    {file ? (
                      <div style={{ textAlign: 'center' }}>

                        <div
                          style={{
                            fontSize: 58,
                            marginBottom: 18
                          }}
                        >
                          📄
                        </div>

                        <div
                          style={{
                            fontWeight: 700,
                            fontSize: 18,
                            color: 'var(--text)',
                            marginBottom: 8
                          }}
                        >
                          {file.name}
                        </div>

                        <div
                          style={{
                            color: 'var(--text2)',
                            fontSize: 14
                          }}
                        >
                          {(file.size / 1024).toFixed(0)} KB
                          {' • '}
                          Click to change file
                        </div>

                      </div>
                    ) : (
                      <div style={{ textAlign: 'center' }}>

                        <div
                          style={{
                            fontSize: 60,
                            marginBottom: 18
                          }}
                        >
                          📂
                        </div>

                        <div
                          style={{
                            fontWeight: 700,
                            fontSize: 20,
                            color: 'var(--text)',
                            marginBottom: 10
                          }}
                        >
                          {isDragActive
                            ? 'Drop your PDF here'
                            : 'Drag & drop a PDF'}
                        </div>

                        <div
                          style={{
                            color: 'var(--text2)',
                            marginBottom: 8
                          }}
                        >
                          or click to browse
                        </div>

                        <div
                          style={{
                            color: 'var(--text3)',
                            fontSize: 13
                          }}
                        >
                          Only PDF documents are accepted
                        </div>

                      </div>
                    )}
                  </div>
                </div>

                {/* Title */}
                <div className="form-group">
                  <label className="label">
                    DOCUMENT TITLE
                  </label>

                  <input
                    className="input"
                    type="text"
                    placeholder="e.g. Service Agreement 2026"
                    value={title}
                    onChange={(e) =>
                      setTitle(e.target.value)
                    }
                  />
                </div>

              </div>

              {/* Recipients Card */}
              <div
                style={{
                  background: 'var(--card)',
                  border: '1px solid var(--border)',
                  borderRadius: 24,
                  padding: 28,
                  marginBottom: 24
                }}
              >

                <div
                  style={{
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                    marginBottom: 20
                  }}
                >

                  <label
                    className="label"
                    style={{
                      marginBottom: 0
                    }}
                  >
                    RECIPIENTS
                  </label>

                  <button
                    type="button"
                    className="btn btn-secondary btn-sm"
                    onClick={addRecipient}
                  >
                    + Add Recipient
                  </button>

                </div>

                <div
                  style={{
                    display: 'flex',
                    flexDirection: 'column',
                    gap: 14
                  }}
                >

                  {recipients.map((r, i) => (

                    <div
                      key={i}
                      style={{
                        display: 'flex',
                        gap: 12,
                        alignItems: 'center'
                      }}
                    >

                      <input
                        className="input"
                        type="email"
                        placeholder="Recipient email"
                        value={r.email}
                        onChange={(e) =>
                          updateRecipient(
                            i,
                            'email',
                            e.target.value
                          )
                        }
                        style={{ flex: 2 }}
                      />

                      <input
                        className="input"
                        type="text"
                        placeholder="Name (optional)"
                        value={r.name}
                        onChange={(e) =>
                          updateRecipient(
                            i,
                            'name',
                            e.target.value
                          )
                        }
                        style={{ flex: 1 }}
                      />

                      {recipients.length > 1 && (
                        <button
                          type="button"
                          className="btn btn-danger btn-sm"
                          onClick={() =>
                            removeRecipient(i)
                          }
                        >
                          ✕
                        </button>
                      )}

                    </div>

                  ))}

                </div>

              </div>

              {/* Message Card */}
              <div
                style={{
                  background: 'var(--card)',
                  border: '1px solid var(--border)',
                  borderRadius: 24,
                  padding: 28
                }}
              >

                <div className="form-group">
                  <label className="label">
                    MESSAGE TO RECIPIENTS (OPTIONAL)
                  </label>

                  <textarea
                    className="input"
                    placeholder="Add a personal message that will be included in the email..."
                    value={message}
                    onChange={(e) =>
                      setMessage(e.target.value)
                    }
                    rows={5}
                    style={{
                      resize: 'vertical'
                    }}
                  />
                </div>

                {/* Buttons */}
                <div
                  style={{
                    display: 'flex',
                    gap: 14,
                    marginTop: 20
                  }}
                >

                  <button
                    type="button"
                    className="btn btn-secondary"
                    onClick={() => navigate('/')}
                  >
                    Cancel
                  </button>

                  <button
                    type="submit"
                    className="btn btn-primary"
                    disabled={loading}
                  >
                    {loading
                      ? '⏳ Uploading...'
                      : '→ Upload & Continue'}
                  </button>

                </div>

              </div>

            </div>

            {/* RIGHT SIDEBAR */}
            <div>

              <div
                style={{
                  background: 'var(--card)',
                  border: '1px solid var(--border)',
                  borderRadius: 24,
                  padding: 28,
                  position: 'sticky',
                  top: 20
                }}
              >

                <h3
                  style={{
                    marginBottom: 24,
                    color: 'var(--text)',
                    fontSize: 22,
                    fontWeight: 700
                  }}
                >
                  Document Summary
                </h3>

                {/* File */}
                <div style={{ marginBottom: 22 }}>

                  <div
                    style={{
                      color: 'var(--text3)',
                      fontSize: 12,
                      marginBottom: 6,
                      letterSpacing: 1
                    }}
                  >
                    FILE
                  </div>

                  <div
                    style={{
                      color: 'var(--text)',
                      fontWeight: 600,
                      wordBreak: 'break-word'
                    }}
                  >
                    {file
                      ? file.name
                      : 'No file selected'}
                  </div>

                </div>

                {/* Recipients */}
                <div style={{ marginBottom: 22 }}>

                  <div
                    style={{
                      color: 'var(--text3)',
                      fontSize: 12,
                      marginBottom: 6,
                      letterSpacing: 1
                    }}
                  >
                    RECIPIENTS
                  </div>

                  <div
                    style={{
                      color: 'var(--text)',
                      fontWeight: 600
                    }}
                  >
                    {
                      recipients.filter(
                        r => r.email.trim()
                      ).length
                    }
                  </div>

                </div>

                {/* Status */}
                <div style={{ marginBottom: 26 }}>

                  <div
                    style={{
                      color: 'var(--text3)',
                      fontSize: 12,
                      marginBottom: 6,
                      letterSpacing: 1
                    }}
                  >
                    STATUS
                  </div>

                  <div
                    style={{
                      color: '#22c55e',
                      fontWeight: 700
                    }}
                  >
                    Ready for Upload
                  </div>

                </div>

                {/* Info Box */}
                <div
                  style={{
                    padding: 18,
                    borderRadius: 16,
                    background:
                      'rgba(99,102,241,0.08)',
                    border:
                      '1px solid rgba(99,102,241,0.2)',
                    color: 'var(--text2)',
                    fontSize: 14,
                    lineHeight: 1.7
                  }}
                >
                  Upload your PDF, configure
                  recipients, and continue to
                  signature placement workflow.
                </div>

              </div>

            </div>

          </div>

        </form>

      </div>

    </Layout>
  );
}